EVAL_SEQ = ""

# F2 scale test (v2, fixed): does a BIGGER Nucleotide-Transformer beat a low-order Markov chain at
# masked reconstruction of real dog (canFam4) sequence? Leakage-free (disjoint Markov + per-base
# marginal NLL). Self-contained; Kaggle T4 (free). Writes /kaggle/working/dog_nt_scale_result.json.
import os, json, math, subprocess, sys
# 4.44.2: has py3.12 wheels + find_pruneable_heads_and_indices + EsmConfig.is_decoder (NT-v2 remote code)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "transformers==4.44.2"], check=False)
import torch, transformers
from transformers import AutoModelForMaskedLM, AutoTokenizer
print("transformers", transformers.__version__, "torch", torch.__version__, flush=True)

DEV = "cuda" if torch.cuda.is_available() else "cpu"
GPU = torch.cuda.get_device_name(0) if DEV == "cuda" else "cpu"
EVAL_BP, N_TOKENS, TRAIN_START, KMER = 1200, 200, 2000, 6
KS = list(range(1, 9))
MODELS = [
    ("NT-v2-100M", "InstaDeepAI/nucleotide-transformer-v2-100m-multi-species"),
    ("NT-v2-500M", "InstaDeepAI/nucleotide-transformer-v2-500m-multi-species"),
    ("NT-2.5B",    "InstaDeepAI/nucleotide-transformer-2.5b-multi-species"),
]
_B = ("A", "C", "G", "T"); _BI = {b: i for i, b in enumerate(_B)}
eval_window = EVAL_SEQ[:EVAL_BP]; disjoint_train = EVAL_SEQ[TRAIN_START:]

def markov_fit(seq, k):
    tables = [dict() for _ in range(k + 1)]
    for i, b in enumerate(seq):
        if b not in _BI: continue
        for o in range(0, k + 1):
            if i < o: continue
            ctx = seq[i - o:i]
            if all(c in _BI for c in ctx):
                tables[o].setdefault(ctx, {x: 0 for x in _B})[b] += 1
    return tables

def base_dist(tables, k, left, exclude=None, alpha=1.0):
    counts = {b: 0 for b in _B}
    for o in range(min(k, len(left)), -1, -1):
        ctx = left[-o:] if o > 0 else ""
        if ctx in tables[o]: counts = dict(tables[o][ctx]); break
    if exclude in _BI and counts[exclude] > 0: counts[exclude] -= 1
    sm = {b: counts[b] + alpha for b in _B}; tot = sum(sm.values())
    return {b: 0.25 for b in _B} if tot <= 0 else {b: sm[b] / tot for b in _B}

def markov_nll_acc(tables, k, seq, idxs, loo, alpha=1.0):
    nll = 0.0; corr = 0; n = 0
    for j in idxs:
        tb = seq[j]
        if tb not in _BI: continue
        d = base_dist(tables, k, seq[max(0, j - k):j], exclude=tb if loo else None, alpha=alpha)
        nll += -math.log(max(d[tb], 1e-12)); corr += (max(_B, key=lambda x: d[x]) == tb); n += 1
    return (nll / n if n else float("inf"), corr / n if n else 0.0)

def nt_scores(model_id, dtype):
    tok = AutoTokenizer.from_pretrained(model_id, trust_remote_code=True)
    model = AutoModelForMaskedLM.from_pretrained(model_id, trust_remote_code=True, torch_dtype=dtype)
    model = model.to(DEV).eval()
    print(f"  loaded {model_id} dtype={dtype}", flush=True)
    enc = tok(eval_window, return_tensors="pt", truncation=True); ids = enc["input_ids"][0]
    strs = tok.convert_ids_to_tokens(ids.tolist()); special = set(tok.all_special_ids); mask_id = tok.mask_token_id
    kmers = []; cur = 0
    for ai, tid in enumerate(ids.tolist()):
        if tid in special: continue
        kmers.append((ai, strs[ai], cur)); cur += len(strs[ai])
    targets = [t for t in range(min(N_TOKENS, len(kmers)))
               if len(kmers[t][1]) == KMER and all(c in _BI for c in kmers[t][1])]
    vocab = tok.get_vocab(); bmap = None
    nll = 0.0; corr = 0; n = 0; masked_idx = []
    for s in range(0, len(targets), 8):
        chunk = targets[s:s + 8]
        batch = ids.unsqueeze(0).repeat(len(chunk), 1).clone()
        for r, tp in enumerate(chunk): batch[r, kmers[tp][0]] = mask_id
        with torch.no_grad():
            logits = model(input_ids=batch.to(DEV)).logits
        probs = torch.softmax(logits.float(), dim=-1).cpu()
        if bmap is None:  # size to the MODEL's logit dim, not the tokenizer vocab (the 2.5B fix)
            V = probs.shape[-1]; bmap = []
            for j in range(KMER):
                m = torch.full((V,), -1, dtype=torch.long)
                for t, i in vocab.items():
                    if i < V and len(t) == KMER and t[j] in _BI: m[i] = _BI[t[j]]
                bmap.append(m)
        for r, tp in enumerate(chunk):
            ai, kmer, bstart = kmers[tp]; dist = probs[r, ai]
            for j in range(KMER):
                tb = kmer[j]
                if tb not in _BI: continue
                acc = torch.zeros(4); mm = bmap[j]; keep = mm >= 0
                acc.index_add_(0, mm[keep], dist[keep])
                nll += -math.log(max(float(acc[_BI[tb]]), 1e-12))
                corr += (int(torch.argmax(acc)) == _BI[tb]); n += 1; masked_idx.append(bstart + j)
    del model
    if DEV == "cuda": torch.cuda.empty_cache()
    return nll / n, corr / n, n, masked_idx

out = {"gpu": GPU, "transformers": transformers.__version__, "eval_bp": EVAL_BP,
       "n_tokens_target": N_TOKENS, "models": {}}
markov_cache = {}
for name, mid in MODELS:
    res = None; last_err = None
    for dt in (torch.float16, torch.float32):
        try:
            res = nt_scores(mid, dt); out.setdefault("_dtype", {})[name] = str(dt); break
        except Exception as e:
            last_err = e
            if DEV == "cuda": torch.cuda.empty_cache()
    if res is None:
        out["models"][name] = {"error": str(last_err)[:300]}; print(name, "ERROR", str(last_err)[:200], flush=True); continue
    nt_nll, nt_acc, n, midx = res
    key = tuple(midx)
    if key not in markov_cache:
        best = None
        for k in KS:
            mnll, macc = markov_nll_acc(markov_fit(disjoint_train, k), k, eval_window, midx, loo=False)
            if best is None or mnll < best[1]: best = (k, mnll, macc)
        markov_cache[key] = best
    bk, mnll, macc = markov_cache[key]
    out["models"][name] = {"nt_per_base_nll": round(nt_nll, 4), "markov_per_base_nll_bestk": round(mnll, 4),
                           "markov_best_k": bk, "PRIMARY_nll_delta_markov_minus_nt": round(mnll - nt_nll, 4),
                           "nt_marginal_accuracy": round(nt_acc, 4), "markov_accuracy": round(macc, 4), "n_bases": n}
    print(name, out["models"][name], flush=True)

with open("/kaggle/working/dog_nt_scale_result.json", "w") as f: json.dump(out, f, indent=2)
print("DONE", json.dumps(out, indent=2))
